    """Schwarzschild radius r_s = 2GM/c^2"""
    return 2 * G * M / c**2

def photon_sphere_radius(M):
    """Photon sphere radius for a non-rotating BH: 1.5 * r_s"""
    return 1.5 * schwarzschild_radius(M)

def critical_impact_parameter(M):
    """Critical angular diameter θ_c = 6√3 GM/(c^2 D) (radians)"""
    return 6 * np.sqrt(3) * G * M / (c**2)

def angular_diameter(M, D):
    """Approximate angular diameter of the black hole (radians)"""
    return 2 * schwarzschild_radius(M) / D

def main():
    # Example: Sgr A* mass
    M = 4.31e6 * M_sun  # kg
    # Distance to Sgr A* (approximate)
    D = 8.102e3 * 3.085677581e16  # 8.102 kpc in meters

    theta_s = critical_impact_parameter(M)
    theta_r = angular_diameter(M, D)

    print(f"Critical impact parameter (radians): {theta_s:.3e}")
    print(f"Approximate angular diameter (radians): {theta_r:.3e}")
    print("Comparison: " + ("θ_r < θ_s" if theta_r < theta_s else "θ_r >= θ_s"))

if __name__ == "__main__":
